//! gRPC transport (tonic): maps protobuf messages to the [`SearchService`].

use std::future::Future;
use std::sync::Arc;
use std::time::Duration;

use tokio::net::TcpListener;
use tonic::transport::Server;
use tonic::transport::server::TcpIncoming;
use tonic::{Request, Response, Status};
use tracing::error;

use crate::engine::QueryMode;
use crate::rank::RankerKind;
use crate::service::SearchService;

/// Code generated by `build.rs` from `proto/search.proto`.
pub mod pb {
    tonic::include_proto!("search.v1");
}

use pb::search_api_server::{SearchApi, SearchApiServer};

const DEFAULT_K: usize = 10;
const MAX_K: usize = 1000;

pub struct GrpcSearch {
    service: Arc<SearchService>,
}

impl GrpcSearch {
    pub fn new(service: Arc<SearchService>) -> Self {
        Self { service }
    }
}

#[tonic::async_trait]
impl SearchApi for GrpcSearch {
    async fn search(&self, request: Request<pb::SearchRequest>) -> Result<Response<pb::SearchResponse>, Status> {
        let request = request.into_inner();
        let ranker = match pb::Ranker::try_from(request.ranker) {
            Ok(pb::Ranker::Unspecified | pb::Ranker::Bm25) => RankerKind::Bm25,
            Ok(pb::Ranker::Tfidf) => RankerKind::TfIdf,
            Err(_) => return Err(Status::invalid_argument(format!("unknown ranker {}", request.ranker))),
        };
        let k = match request.k as usize {
            0 => DEFAULT_K,
            k => k.min(MAX_K),
        };
        let mode = if request.any_terms {
            QueryMode::AnyTerms
        } else {
            QueryMode::Boolean
        };

        let response = self
            .service
            .search(&request.query, mode, k, ranker)
            .await
            .map_err(|err| {
                if err.is_invalid_query() {
                    Status::invalid_argument(err.to_string())
                } else {
                    error!(error = %err, query = %request.query, "search failed");
                    Status::internal("search failed")
                }
            })?;

        let hits = response
            .results
            .hits
            .into_iter()
            .map(|hit| pb::Hit {
                doc_id: hit.doc_id,
                external_id: hit.external_id,
                title: hit.title,
                url: hit.url,
                score: hit.score,
                snippet: hit.snippet,
            })
            .collect();
        Ok(Response::new(pb::SearchResponse {
            hits,
            total_matches: response.results.total_matches,
            cache_hit: response.cache_hit,
            took_micros: u64::try_from(response.took.as_micros()).unwrap_or(u64::MAX),
        }))
    }

    async fn stats(&self, _request: Request<pb::StatsRequest>) -> Result<Response<pb::StatsResponse>, Status> {
        let engine = self.service.engine();
        let index = engine.stats();
        let hot = engine.hot_term_stats();
        let cache = self.service.cache().map(|cache| cache.stats());
        Ok(Response::new(pb::StatsResponse {
            num_docs: index.num_docs,
            num_terms: index.num_terms,
            avg_doc_len: index.avg_doc_len(),
            index_version: index.index_version.clone(),
            codec: format!("{:?}", index.codec),
            hot_term_capacity: hot.capacity as u64,
            hot_terms_resident: hot.resident_terms as u64,
            hot_term_bytes: hot.resident_bytes as u64,
            hot_term_hits: hot.hits,
            hot_term_misses: hot.misses,
            result_cache_enabled: cache.is_some(),
            result_cache_hits: cache.map_or(0, |c| c.hits),
            result_cache_misses: cache.map_or(0, |c| c.misses),
            result_cache_errors: cache.map_or(0, |c| c.errors),
        }))
    }
}

/// Serves the API on `listener` until `shutdown` resolves, then stops taking
/// new connections and lets in-flight requests finish.
pub async fn serve(
    listener: TcpListener,
    service: Arc<SearchService>,
    shutdown: impl Future<Output = ()>,
) -> Result<(), tonic::transport::Error> {
    Server::builder()
        .timeout(Duration::from_secs(30))
        .add_service(SearchApiServer::new(GrpcSearch::new(service)))
        .serve_with_incoming_shutdown(TcpIncoming::from(listener), shutdown)
        .await
}

/// Resolves on Ctrl-C, or on SIGTERM (what `docker stop` and Kubernetes send).
pub async fn shutdown_signal() {
    let ctrl_c = async {
        if let Err(error) = tokio::signal::ctrl_c().await {
            error!(%error, "cannot listen for Ctrl-C");
            std::future::pending::<()>().await;
        }
    };
    #[cfg(unix)]
    let terminate = async {
        match tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()) {
            Ok(mut signal) => {
                signal.recv().await;
            }
            Err(error) => {
                error!(%error, "cannot listen for SIGTERM");
                std::future::pending::<()>().await;
            }
        }
    };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        () = ctrl_c => {}
        () = terminate => {}
    }
}
